<div class="lb" id="lb" role="dialog" aria-modal="true" aria-label="Enlarged screenshot">
  <button class="x" id="lbx" aria-label="Close"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round"><path d="M18 6 6 18M6 6l12 12"/></svg></button>
  <img id="lbi" src="data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7" alt="" decoding="async">
  <div class="cap" id="lbc"></div>
</div>

<script>
(function(){
  "use strict";
  var $  = function(s,c){return (c||document).querySelector(s);};
  var $$ = function(s,c){return Array.prototype.slice.call((c||document).querySelectorAll(s));};
  var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  if(/[?&]embed=1\b/.test(location.search)) document.body.classList.add('embed');

  /* progress */
  var prog = $('#prog');
  function onScroll(){
    var h = document.documentElement.scrollHeight - window.innerHeight;
    prog.style.width = (h>0 ? Math.min(100,(window.scrollY/h)*100) : 0) + '%';
  }
  window.addEventListener('scroll', onScroll, {passive:true}); onScroll();

  /* reveal */
  var items = $$('.rv');
  if(!reduce && 'IntersectionObserver' in window){
    var io = new IntersectionObserver(function(es){
      es.forEach(function(e){ if(e.isIntersecting){ e.target.classList.add('in'); io.unobserve(e.target); } });
    },{rootMargin:'0px 0px -8% 0px', threshold:.08});
    items.forEach(function(el,i){ el.style.transitionDelay = Math.min(i%4*80,240)+'ms'; io.observe(el); });
  } else { items.forEach(function(el){ el.classList.add('in'); }); }

  /* count up */
  if(!reduce && 'IntersectionObserver' in window){
    var cio = new IntersectionObserver(function(es){
      es.forEach(function(e){
        if(!e.isIntersecting) return;
        var el=e.target, t=parseFloat(el.getAttribute('data-count'))||0, t0=null, dur=950;
        function tick(ts){
          if(t0===null) t0=ts;
          var p=Math.min((ts-t0)/dur,1), v=Math.round(t*(1-Math.pow(1-p,3)));
          el.textContent = v;
          if(p<1) requestAnimationFrame(tick);
        }
        requestAnimationFrame(tick); cio.unobserve(el);
      });
    },{threshold:.4});
    $$('[data-count]').forEach(function(el){ cio.observe(el); });
  }

  /* 3D #1 — pointer tilt on the lookbook stack */
  var stage=$('#stage'), stack=$('#stack');
  if(stage && stack && !reduce && window.matchMedia('(hover:hover) and (pointer:fine)').matches){
    var raf=null;
    stage.addEventListener('pointermove', function(ev){
      var r = stage.getBoundingClientRect();
      var px = (ev.clientX-r.left)/r.width - .5;
      var py = (ev.clientY-r.top )/r.height - .5;
      if(raf) return;
      raf = requestAnimationFrame(function(){
        stack.style.transform = 'rotateX('+(12-py*10)+'deg) rotateY('+(-13+px*10)+'deg)';
        var ps = $$('.panel', stage);
        ps.forEach(function(p,i){
          if(i>=2) return;
          var dz = (i===0 ? 1 : 2);
          p.style.transform = 'translate3d('+(-4.5*dz+px*-6*dz)+'%,'+(-3.4*dz+py*-8*dz)+'%,'+(-56*dz)+'px)';
        });
        raf=null;
      });
    },{passive:true});
    stage.addEventListener('pointerleave', function(){
      stack.style.transform=''; $$('.panel',stage).forEach(function(p){ p.style.transform=''; });
    });
  }

  /* 3D #2 — layered architecture tilt */
  var layers=$('#layers');
  if(layers && !reduce && window.matchMedia('(hover:hover) and (pointer:fine)').matches){
    layers.addEventListener('pointermove', function(ev){
      var r=layers.getBoundingClientRect();
      var py=(ev.clientY-r.top)/r.height-.5;
      layers.querySelector('.layers').style.transform = 'rotateY('+(py*-14)+'deg)';
    },{passive:true});
    layers.addEventListener('pointerleave', function(){ layers.querySelector('.layers').style.transform=''; });
  }

  /* 3D #3 — vitals bars */
  var chart=$('#chart');
  if(chart && 'IntersectionObserver' in window){
    var bio=new IntersectionObserver(function(es){
      es.forEach(function(e){ if(e.isIntersecting){ e.target.classList.add('in'); bio.unobserve(e.target);} });
    },{threshold:.35});
    bio.observe(chart);
  } else if(chart){ chart.classList.add('in'); }

  /* lightbox */
  var lb=$('#lb'), lbi=$('#lbi'), lbc=$('#lbc');
  function open(src,cap){ lbi.src=src; lbi.alt=cap||''; lbc.textContent=cap||''; lb.classList.add('on'); document.body.style.overflow='hidden'; }
  function close(){ lb.classList.remove('on'); document.body.style.overflow=''; }
  $$('.plate[data-lb]').forEach(function(p){
    p.setAttribute('tabindex','0'); p.setAttribute('role','button');
    p.addEventListener('click', function(){ open(p.getAttribute('data-lb'), p.getAttribute('data-cap')); });
    p.addEventListener('keydown', function(e){ if(e.key==='Enter'||e.key===' '){ e.preventDefault(); open(p.getAttribute('data-lb'), p.getAttribute('data-cap')); }});
  });
  $('#lbx').addEventListener('click', close);
  lb.addEventListener('click', function(e){ if(e.target===lb) close(); });
  document.addEventListener('keydown', function(e){ if(e.key==='Escape' && lb.classList.contains('on')) close(); });

  /* image safety */
  $$('img').forEach(function(im){
    im.addEventListener('error', function(){
      im.style.background='linear-gradient(135deg,#0F2A26,#07110F)';
      im.style.minHeight='160px';
    },{once:true});
  });
})();
</script>
</body>
